async function query(request, message = 'Operacja Supabase nie powiodĹ‚a siÄ™.') { const { data, error } = await request; if (error) { if (error.status === 401 || /JWT|session/i.test(error.message)) await sb.auth.signOut(); throw new Error(error.message || message); } return data; }

