function manualMarkup(source) {
  if (!source) return '<p class="manual-empty">Brak opisu w manualu.</p>';
  const lines = source.split(/\r?\n/).map(line => line.trim()).filter(Boolean), html = [];
  for (let index = 0; index < lines.length;) {
    if (lines[index].startsWith('|')) {
      const rows = [];
      while (index < lines.length && lines[index].startsWith('|')) { if (!/^\|\s*:?-{2,}/.test(lines[index])) rows.push(lines[index].split('|').slice(1,-1).map(cell => esc(cell.trim()))); index++; }
      if (rows.length) html.push(`<div class="manual-table-wrap"><table class="manual-table"><tbody>${rows.map((row, rowIndex) => `<tr>${row.map(cell => `<${rowIndex === 0 ? 'th' : 'td'}>${cell}</${rowIndex === 0 ? 'th' : 'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`);
    } else if (/^[-*]\s+/.test(lines[index])) {
      const items = []; while (index < lines.length && /^[-*]\s+/.test(lines[index])) items.push(`<li>${esc(lines[index].replace(/^[-*]\s+/, ''))}</li>`), index++;
      html.push(`<ul>${items.join('')}</ul>`);
    } else if (/^\d+\.\s+/.test(lines[index])) {
      const items = []; while (index < lines.length && /^\d+\.\s+/.test(lines[index])) items.push(`<li>${esc(lines[index].replace(/^\d+\.\s+/, ''))}</li>`), index++;
      html.push(`<ol>${items.join('')}</ol>`);
    } else { html.push(`<p>${esc(lines[index])}</p>`); index++; }
  }
  return html.join('');
}

function descriptionFor(test, locale = 'pl') {
  const descriptions = state.cfg.descriptionsByTestId?.[test.testId] || {};
  return descriptions[locale] || descriptions.pl || descriptions.en || { purpose: test.descriptionShort, reportDescription: test.descriptionShort, scoringCriteria: test.criteriaSummary, sourceReference: test.sourceReference };
}

function descriptionPanel(test) {
  const description = descriptionFor(test);
  return `<details class="criteria"><summary>Opis i kryteria oceny</summary><p class="criteria-summary">${esc(description.reportDescription || description.purpose)} <strong>${esc(description.sourceReference || test.sourceReference)}</strong></p><div class="manual-grid"><section><h4>Jak wykonaÄ‡ test</h4>${manualMarkup(description.procedure)}</section>${description.verbalInstruction ? `<section><h4>Instrukcja dla klienta</h4>${manualMarkup(description.verbalInstruction)}</section>` : ''}${description.sideDefinition ? `<section class="manual-side"><h4>Jak rozpoznaÄ‡ stronÄ™</h4>${manualMarkup(description.sideDefinition)}</section>` : ''}<section><h4>Punktacja i odpowiedzi</h4>${manualMarkup(description.scoringCriteria || test.criteriaSummary)}</section></div></details>`;
}

async function loadConfiguration() {
  const [types, tests, screenTests, sets, options, fields, rules, descriptions] = await Promise.all([
    ...['screen_types','tests','screen_tests','answer_sets','answer_options','test_fields','effect_rules'].map(table => query(sb.from(table).select('*'))),
    query(sb.from('test_descriptions').select('*').eq('is_active', true))
  ]);
  const mappedTests = tests.map(x => ({ testId: x.test_id, code: x.code, name: x.name, descriptionShort: x.description_short, criteriaSummary: x.criteria_summary, sourceReference: x.source_reference, isActive: x.is_active }));
  const mappedScreenTests = screenTests.map(x => ({ screenTestId: x.screen_test_id, screenTypeId: x.screen_type_id, testId: x.test_id, sortOrder: x.sort_order, calculationType: x.calculation_type, isActive: x.is_active, parentScreenTestId: x.parent_screen_test_id || null }));
  const mappedSets = sets.map(set => ({ answerSetId: set.answer_set_id, code: set.code, name: set.name, valueKind: set.value_kind, isActive: set.is_active, options: options.filter(o => o.answer_set_id === set.answer_set_id).sort((a,b) => a.sort_order-b.sort_order).map(o => ({ answerOptionId: o.answer_option_id, answerSetId: o.answer_set_id, code: o.code, labelPl: o.label_pl, numericValue: o.numeric_value, sortOrder: o.sort_order })) }));
  const mappedFields = fields.map(x => ({ testFieldId: x.test_field_id, screenTestId: x.screen_test_id, code: x.code, labelPl: x.label_pl, answerSetId: x.answer_set_id, answerSetCode: mappedSets.find(s => s.answerSetId === x.answer_set_id)?.code, sideMode: x.side_mode, attemptMode: x.attempt_mode, isScoringInput: x.is_scoring_input, helpText: x.help_text, sortOrder: x.sort_order }));
  const optionsById = Object.fromEntries(mappedSets.flatMap(set => set.options.map(option => [option.answerOptionId, option])));
  const mappedRules = rules.map(x => ({ effectRuleId: x.effect_rule_id, screenTypeId: x.screen_type_id, sourceTestFieldId: x.source_test_field_id, triggerAnswerCode: optionsById[x.trigger_answer_option_id]?.code, sourceSideCondition: x.source_side_condition, targetScreenTestId: x.target_screen_test_id, effectType: x.effect_type, effectValue: x.effect_value, isActive: x.is_active, reasonTemplate: x.reason_template }));
  const descriptionsByTestId = {};
  descriptions.forEach(item => { (descriptionsByTestId[item.test_id] ||= {})[item.locale] = { purpose: item.purpose, procedure: item.procedure, verbalInstruction: item.verbal_instruction, sideDefinition: item.side_definition, scoringCriteria: item.scoring_criteria, reportDescription: item.report_description, sourceReference: item.source_reference, manualVersion: item.manual_version, contentHash: item.content_hash }; });
  const activeManualVersion = descriptions.find(item => item.locale === 'pl')?.manual_version || descriptions[0]?.manual_version || null;
  return { screenTypes: types, tests: mappedTests, screenTests: mappedScreenTests, answerSets: mappedSets, fields: mappedFields, rules: mappedRules, descriptionsByTestId, activeManualVersion, testsById: Object.fromEntries(mappedTests.map(x => [x.testId, x])), screenTestsById: Object.fromEntries(mappedScreenTests.map(x => [x.screenTestId, x])), fieldsById: Object.fromEntries(mappedFields.map(x => [x.testFieldId, x])), fieldsByCode: Object.fromEntries(mappedFields.map(x => [x.code, x])), optionsById, optionsByCode: Object.fromEntries(mappedSets.flatMap(set => set.options.map(option => [option.code, option]))) };
}

function renderAuth(mode = 'login') {
  state.user = null; state.profileUser = null; setNav('');
  const recovery = mode === 'recovery';
  app.innerHTML = `<section class="auth-shell"><div class="auth-story"><div><div class="eyebrow">KB Trener</div><h1>Quick<br>Screen</h1><p>Prywatna przestrzeĹ„ do prowadzenia badaĹ„, historii wynikĂłw i raportĂłw.</p></div><small>Dane chronione przez Supabase Auth i Row Level Security.</small></div><div class="auth-form"><div class="eyebrow">${recovery ? 'Nowe hasĹ‚o' : mode === 'signup' ? 'Nowe konto' : 'Bezpieczny dostÄ™p'}</div><h2>${recovery ? 'Ustaw nowe hasĹ‚o' : mode === 'signup' ? 'ZaĹ‚ĂłĹĽ konto' : 'Zaloguj siÄ™'}</h2><p>${recovery ? 'WprowadĹş nowe hasĹ‚o dla swojego konta.' : 'DostÄ™p wymaga konta uĹĽytkownika.'}</p><form id="auth-form" class="form-stack">${recovery ? '' : '<label class="field">E-mail<input name="email" type="email" autocomplete="email" required></label>'}<label class="field">HasĹ‚o<input name="password" type="password" autocomplete="${recovery ? 'new-password' : 'current-password'}" minlength="6" required></label><button class="btn btn-primary">${recovery ? 'Zapisz hasĹ‚o' : mode === 'signup' ? 'ZaĹ‚ĂłĹĽ konto' : 'Zaloguj siÄ™'}</button></form>${recovery ? '' : `<div class="auth-links"><button class="text-button" data-auth-mode="${mode === 'signup' ? 'login' : 'signup'}">${mode === 'signup' ? 'Mam juĹĽ konto' : 'ZaĹ‚ĂłĹĽ konto'}</button><button class="text-button" data-action="forgot-password">Nie pamiÄ™tam hasĹ‚a</button></div>`}</div></section>`;
  document.querySelector('#auth-form').addEventListener('submit', async event => { event.preventDefault(); const button = event.submitter; button.disabled = true; try { const values = Object.fromEntries(new FormData(event.currentTarget)); if (recovery) { const { error } = await sb.auth.updateUser({ password: values.password }); if (error) throw error; notify('HasĹ‚o zostaĹ‚o zmienione.'); await boot(); } else if (mode === 'signup') { const { data, error } = await sb.auth.signUp({ email: values.email, password: values.password, options: { emailRedirectTo: location.href.split('#')[0] } }); if (error) throw error; if (!data.session) { notify('SprawdĹş pocztÄ™ i potwierdĹş konto.'); renderAuth('login'); } } else { const { error } = await sb.auth.signInWithPassword(values); if (error) throw new Error('NieprawidĹ‚owy e-mail lub hasĹ‚o.'); } } catch (error) { fail(error); button.disabled = false; } });
}

async function boot() {
  loading('Sprawdzam sesjÄ™â€¦');
  const { data, error } = await sb.auth.getSession();
  if (error || !data.session) return renderAuth();
  state.user = data.session.user;
  const [profile, certifications] = await Promise.all([
    query(sb.from('profiles').select('*').eq('id', state.user.id).single()),
    query(sb.from('trainer_certifications').select('*').eq('trainer_id', state.user.id).eq('is_active', true).order('sort_order'))
  ]);
  state.profileUser = { ...profile, certifications };
  state.cfg = await loadConfiguration();
  await showClients();
}

async function fetchClients() {
  const rows = await query(sb.from('clients').select('*,assessments(assessment_id,assessment_date,status,assessment_answers(*),applied_effects(*))').order('last_name').order('first_name'));
  return rows.map(row => { const assessments = (row.assessments || []).map(item => hydrateAssessment(item, state.cfg)); const latest = assessments.filter(x => x.status !== 'archived').sort((a,b) => b.assessmentDate.localeCompare(a.assessmentDate))[0]; return { clientId: row.client_id, firstName: row.first_name, lastName: row.last_name, email: row.email, isArchived: row.is_archived, createdAt: row.created_at, lastAssessmentDate: latest?.assessmentDate || null, lastTotalScreenScore: latest?.totalScreenScore ?? null }; });
}

