function renderFatal(error) { app.innerHTML = `<section class="setup-card"><div class="eyebrow">Nie udaĹ‚o siÄ™ wczytaÄ‡ danych</div><h1>SprĂłbuj ponownie</h1><p>${esc(error.message)}</p><button class="btn btn-dark" data-action="retry">PonĂłw</button></section>`; }

function openClientForm(client = null) {
  modal.hidden = false; modal.innerHTML = `<section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><h2>${client ? 'Edytuj klienta' : 'Nowy klient'}</h2><button class="icon-btn" data-action="close-modal" aria-label="Zamknij">Ă—</button></header><form id="client-form" class="form-stack"><label class="field">ImiÄ™<input name="firstName" required value="${esc(client?.firstName || '')}" autocomplete="given-name"></label><label class="field">Nazwisko<input name="lastName" required value="${esc(client?.lastName || '')}" autocomplete="family-name"></label><label class="field">E-mail<input name="email" type="email" required value="${esc(client?.email || '')}" autocomplete="email"></label><div class="form-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Anuluj</button><button class="btn btn-primary">Zapisz klienta</button></div></form></section>`;
  document.querySelector('#client-form').addEventListener('submit', async event => { event.preventDefault(); const button = event.submitter; button.disabled = true; try { const clean = validateClient(Object.fromEntries(new FormData(event.currentTarget))); const duplicate = await query(sb.from('clients').select('client_id').ilike('email', clean.email).neq('client_id', client?.clientId || '00000000-0000-0000-0000-000000000000').limit(1)); let id = client?.clientId; if (client) await query(sb.from('clients').update({ first_name: clean.firstName, last_name: clean.lastName, email: clean.email }).eq('client_id', id)); else { const created = await query(sb.from('clients').insert({ owner_id: state.user.id, first_name: clean.firstName, last_name: clean.lastName, email: clean.email }).select('client_id').single()); id = created.client_id; } closeModal(); notify(duplicate.length ? 'Dane zapisane. Inny klient ma ten sam adres e-mail.' : 'Dane klienta zapisane.'); await showProfile(id); } catch (error) { button.disabled = false; fail(error); } });
}

