      <header><div class="wizard-test-heading"><span class="wizard-test-icon">${data.step+1}</span><div><span class="stitch-overline">TEST ${data.step+1} Z ${tests.length}</span><h1>${esc(test.name)}</h1></div></div><button class="criteria-trigger" data-action="open-criteria" aria-controls="criteria-sheet">â–¤ Kryteria</button></header>
