function findingsMarkup(data){return `<div class="finding-list">${data.priorityFindings.map(item=>`<div class="finding" data-status="${item.severity}"><strong>${esc(item.title)}</strong><div>${esc(item.detail)}</div></div>`).join('')||'<p>Nie zarejestrowano priorytetowych flag.</p>'}</div>`}
