function reportTestFacts(item){const scoreFacts=[];if(item.rawScores.left!=null)scoreFacts.push(`Lewa: ${item.rawScores.left}`);if(item.rawScores.right!=null)scoreFacts.push(`Prawa: ${item.rawScores.right}`);if(item.finalScore!=null)scoreFacts.push(`Wynik koĹ„cowy: ${item.finalScore}`);item.answers.filter(answer=>answer.value).forEach(answer=>scoreFacts.push(`${answer.side==='left'?'L Â· ':answer.side==='right'?'P Â· ':''}${answer.field}: ${answer.value}`));return [...new Set(scoreFacts)]}
function reportTestMarkup(item,showDescription){const photo=item.photos[0];return `<article class="report-test-card${item.parentTestId?' report-clearing-child':''}" data-status="${item.status.level}">${item.parentTestId?'<div class="report-clearing-label">Test clearing â€” powiÄ…zany z testem nadrzÄ™dnym</div>':''}<header class="report-test-head"><h3>${item.index}. ${esc(item.name)}</h3><span class="status-badge" data-status="${item.status.level}" data-icon="${item.status.icon}">${item.finalScore==null?esc(item.status.label):`Wynik: ${item.finalScore} Â· ${esc(item.status.label)}`}</span></header><div class="report-test-body">${photo?.dataUrl?`<img class="report-test-photo" src="${photo.dataUrl}" alt="Dokumentacja testu ${esc(item.name)}">`:''}${showDescription?`<div class="report-test-description">${esc(item.description)}</div>`:''}</div><div class="report-test-results">${reportTestFacts(item).map(fact=>`<span class="result-fact">${esc(fact)}</span>`).join('')}${item.asymmetry?'<span class="status-badge" data-status="attention" data-icon="!">Asymetria</span>':''}</div>${item.note?`<div class="trainer-note"><strong>Notatka trenera</strong><br>${esc(item.note)}</div>`:''}</article>`}
