let pdfAssetsReady=false;async function ensurePdfAssets(){if(pdfAssetsReady)return;const[interRegular,interBold,outfitRegular,outfitBold]=await Promise.all(['Inter-Regular.ttf','Inter-Bold.ttf','Outfit-Regular.ttf','Outfit-Bold.ttf'].map(name=>assetDataUrl(`./assets/${name}`)));pdfMake.addVirtualFileSystem({'Inter-Regular.ttf':interRegular.split(',')[1],'Inter-Bold.ttf':interBold.split(',')[1],'Outfit-Regular.ttf':outfitRegular.split(',')[1],'Outfit-Bold.ttf':outfitBold.split(',')[1]});pdfMake.addFonts({Inter:{normal:'Inter-Regular.ttf',bold:'Inter-Bold.ttf',italics:'Inter-Regular.ttf',bolditalics:'Inter-Bold.ttf'},Outfit:{normal:'Outfit-Regular.ttf',bold:'Outfit-Bold.ttf',italics:'Outfit-Regular.ttf',bolditalics:'Outfit-Bold.ttf'}});pdfAssetsReady=true}
const pdfBlob=definition=>pdfMake.createPdf(definition).getBlob();
async function saveReportInstance(data,blob){const snapshot=reportSnapshot(data);const instance=await query(sb.from('report_instances').insert({client_id:data.client.clientId,assessment_id:data.latest.assessmentId,trainer_id:state.user.id,report_profile_code:data.reportProfile,manual_extensions:data.requestedSections,generator_version:data.generatorVersion,manual_version:data.manualVersion,snapshot,document_status:'generating'}).select('report_instance_id').single());await query(sb.from('report_instance_sections').insert(data.enabledSections.map((section_code,index)=>({report_instance_id:instance.report_instance_id,section_code,sort_order:index+1}))));const path=`${state.user.id}/${instance.report_instance_id}.pdf`;const{error}=await sb.storage.from('report-pdfs').upload(path,blob,{contentType:'application/pdf',upsert:false});if(error){await query(sb.from('report_instances').update({document_status:'failed'}).eq('report_instance_id',instance.report_instance_id));throw error}await query(sb.from('report_instances').update({pdf_storage_path:path,document_status:'ready'}).eq('report_instance_id',instance.report_instance_id));return instance.report_instance_id}
async function downloadPdf(){const data=state.report||buildReportData(),filename=`FMS_Quick_Screen_${fileSafe(data.client.lastName)}_${data.latest.assessmentDate}.pdf`;await ensurePdfAssets();if(!data.logoData)data.logoData=await assetDataUrl('./assets/kb-logo.png');const blob=await pdfBlob(createFmsPdfDefinition(data));await saveReportInstance(data,blob);const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);notify('PDF i niezmienny snapshot zostaĹ‚y zapisane.')}
async function prepareEmail(){const data=state.report||buildReportData(),subject=`FMS Quick Screen - ${data.client.firstName} ${data.client.lastName} - ${data.latest.assessmentDate}`,body='DzieĹ„ dobry,\n\nw zaĹ‚Ä…czniku znajduje siÄ™ raport FMS Quick Screen.\n\nRaport opisuje zapisane wyniki i nie stanowi diagnozy ani zalecenia terapeutycznego.\n\nPobierz PDF z QuickScreen i doĹ‚Ä…cz go do tej wiadomoĹ›ci.';await downloadPdf();location.href=`mailto:${encodeURIComponent(data.client.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}

async function showConfig(){setNav('config');loading('WczytujÄ™ konfiguracjÄ™â€¦');try{state.cfg=await loadConfiguration();app.innerHTML=`<section class="hero"><div><div class="eyebrow">Konfiguracja protokoĹ‚u</div><h1>ReguĹ‚y i katalog</h1><p class="hero-copy">Zmiana reguĹ‚ jest dostÄ™pna wyĹ‚Ä…cznie administratorowi.</p></div></section><section class="panel"><header class="panel-head"><h2>ReguĹ‚y clearing</h2><small>${state.cfg.rules.length} reguĹ‚y</small></header>${state.cfg.rules.map(rule=>`<div class="rule-card"><div><strong>${esc(rule.reasonTemplate)}</strong><p>${esc(rule.sourceTestFieldId)} â†’ ${esc(rule.targetScreenTestId)} Â· wynik ${rule.effectValue}</p></div><button class="btn ${rule.isActive?'btn-dark':''}" data-rule="${rule.effectRuleId}" data-active="${rule.isActive}" ${state.profileUser.role!=='admin'?'disabled title="Tylko administrator"':''}>${rule.isActive?'Aktywna':'WyĹ‚Ä…czona'}</button></div>`).join('')}</section><section class="panel" style="margin-top:20px"><header class="panel-head"><h2>Katalog testĂłw</h2></header>${state.cfg.tests.map(test=>`<div class="rule-card"><div><strong>${esc(test.name)}</strong><p>${esc(test.criteriaSummary)} Â· ${esc(test.sourceReference)}</p></div></div>`).join('')}</section>`}catch(error){renderFatal(error)}}
function showUserProfile(){setNav('profile-user');const certifications=state.profileUser.certifications||[];app.innerHTML=`<section class="panel"><div class="eyebrow">Konto trenera</div><h1>${esc(state.profileUser.display_name||state.user.email)}</h1><p>${esc(state.user.email)}</p><p>Rola: <strong>${esc(state.profileUser.role)}</strong></p><div class="toolbar"><button class="btn" data-action="change-password">ZmieĹ„ hasĹ‚o</button>${state.profileUser.role==='admin'?'<button class="btn" data-action="team">ZespĂłĹ‚</button>':''}<button class="btn btn-dark" data-action="sign-out">Wyloguj</button></div></section><section class="panel" style="margin-top:20px"><header class="panel-head"><h2>Certyfikacje</h2><button class="btn btn-primary" data-action="new-certification">Dodaj certyfikacjÄ™</button></header>${certifications.map(item=>`<div class="history-row"><span><strong>${esc(item.name)}</strong>${item.issuer?` Â· ${esc(item.issuer)}`:''}</span><span><button class="btn btn-quiet" data-certification='${esc(JSON.stringify(item))}'>Edytuj</button><button class="btn btn-quiet" data-delete-certification="${item.certification_id}">UsuĹ„</button></span></div>`).join('')||'<p>Dodaj pierwszÄ… certyfikacjÄ™ trenera.</p>'}</section>`}
function passwordModal(){modal.hidden=false;modal.innerHTML='<section class="modal"><header class="modal-head"><h2>ZmieĹ„ hasĹ‚o</h2><button class="icon-btn" data-action="close-modal">Ă—</button></header><form id="password-form" class="form-stack"><label class="field">Nowe hasĹ‚o<input name="password" type="password" minlength="6" required></label><button class="btn btn-primary">Zapisz hasĹ‚o</button></form></section>';document.querySelector('#password-form').onsubmit=async event=>{event.preventDefault();try{const password=new FormData(event.currentTarget).get('password'),{error}=await sb.auth.updateUser({password});if(error)throw error;closeModal();notify('HasĹ‚o zostaĹ‚o zmienione.')}catch(error){fail(error)}}}

document.addEventListener('click', async event => {
  const quickTest = event.target.closest('.client-action .mini-action');
  if (!quickTest) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  try { await showProfile(quickTest.dataset.client); await beginAssessment(); } catch (error) { fail(error); }
});

document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;const action=button.dataset.action;try{if(button.dataset.authMode)return renderAuth(button.dataset.authMode);if(action==='forgot-password'){const email=prompt('Podaj adres e-mail konta:');if(email){const{error}=await sb.auth.resetPasswordForEmail(normalizeEmail(email),{redirectTo:location.href.split('#')[0]});if(error)throw error;notify('Link do zmiany hasĹ‚a zostaĹ‚ wysĹ‚any.')}return}if(action==='retry')return boot();if(action==='home')return showClients();if(action==='config')return showConfig();if(action==='team')return showTeamAdmin();if(action==='new-certification')return openCertificationForm();if(button.dataset.certification)return openCertificationForm(JSON.parse(button.dataset.certification));if(button.dataset.deleteCertification){await query(sb.from('trainer_certifications').update({is_active:false}).eq('certification_id',button.dataset.deleteCertification));return boot()}if(action==='new-discipline')return openDisciplineForm();if(button.dataset.discipline)return openDisciplineForm(JSON.parse(button.dataset.discipline));if(button.dataset.deleteDiscipline){await query(sb.from('client_disciplines').delete().eq('client_discipline_id',button.dataset.deleteDiscipline));return showProfile(state.profile.client.clientId)}if(button.dataset.removeAssignment){await query(sb.from('trainer_client_access').update({is_active:false}).eq('access_id',button.dataset.removeAssignment));return showTeamAdmin();}if(action==='profile-user')return showUserProfile();if(action==='new-client')return openClientForm();if(action==='close-modal')return closeModal();if(button.dataset.client)return showProfile(button.dataset.client);if(action==='edit-client')return openClientForm(state.profile.client);if(action==='new-assessment')return beginAssessment();if(action==='cancel-assessment'){if(confirm('ZamknÄ…Ä‡ badanie? Wprowadzone odpowiedzi pozostanÄ… tymczasowo w tej przeglÄ…darce.'))return renderProfile()}if(button.dataset.step!=null){state.assessment.step=Number(button.dataset.step);storeDraft();return renderAssessment()}if(button.hasAttribute('data-answer')){state.assessment.answers[keyFor(button.dataset.field,button.dataset.side)]=button.dataset.option;storeDraft();return renderAssessment()}if(action==='previous-step'){state.assessment.step--;storeDraft();return renderAssessment()}if(action==='next-step'){if(!testComplete(testModel()[state.assessment.step]))return notify('UzupeĹ‚nij wszystkie odpowiedzi w tym teĹ›cie.',true);state.assessment.step++;storeDraft();return renderAssessment()}if(action==='finish-assessment')return finishAssessment(button);if(button.dataset.editAssessment)return beginAssessment(state.profile.assessments.find(x=>x.assessmentId===button.dataset.editAssessment));if(button.dataset.openAssessment)return openAssessment(button.dataset.openAssessment);if(action==='archive-client'||action==='restore-client'){await query(sb.from('clients').update({is_archived:action==='archive-client'}).eq('client_id',state.profile.client.clientId));return showProfile(state.profile.client.clientId,true)}if(button.dataset.archiveAssessment||button.dataset.restoreAssessment){const id=button.dataset.archiveAssessment||button.dataset.restoreAssessment,status=button.dataset.archiveAssessment?'archived':'completed';await query(sb.from('assessments').update({status}).eq('assessment_id',id));return showProfile(state.profile.client.clientId,true)}if(action==='report')return showReport();if(action==='back-profile')return renderProfile();if(action==='print-report')return window.print();if(action==='download-pdf')return downloadPdf();if(action==='email-report')return prepareEmail();if(button.dataset.downloadAttachment)return downloadAttachment(button.dataset.path);if(button.dataset.deleteAttachment)return deleteAttachment(button.dataset.deleteAttachment,button.dataset.path);if(button.dataset.rule){await query(sb.from('effect_rules').update({is_active:button.dataset.active!=='true'}).eq('effect_rule_id',button.dataset.rule));notify('ReguĹ‚a zaktualizowana.');return showConfig()}if(action==='change-password')return passwordModal();if(action==='sign-out')return sb.auth.signOut()}catch(error){fail(error)}});
modal.addEventListener('click',event=>{if(event.target===modal)closeModal()});
sb.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY')return renderAuth('recovery');if(event==='SIGNED_OUT')return renderAuth();if(session&&!state.user)setTimeout(()=>boot().catch(renderFatal),0)});
document.addEventListener('click',async event=>{const path=event.target.closest('button')?.dataset.reportPath;if(!path)return;try{const{data,error}=await sb.storage.from('report-pdfs').createSignedUrl(path,60);if(error)throw error;window.open(data.signedUrl,'_blank','noopener')}catch(error){fail(error)}});
function openRuleForm(){if(state.profileUser.role!=='admin')return notify('Panel reguĹ‚ jest dostÄ™pny tylko administratorowi.',true);const fields=state.cfg.fields.filter(field=>field.isScoringInput);modal.hidden=false;modal.innerHTML=`<section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><h2>Nowa reguĹ‚a clearing</h2><button class="icon-btn" data-action="close-modal">Ă—</button></header><form id="rule-form" class="form-stack"><label class="field">Pole ĹşrĂłdĹ‚owe<select name="source_test_field_id" required>${fields.map(field=>`<option value="${field.testFieldId}">${esc(field.labelPl)}</option>`).join('')}</select></label><label class="field">OdpowiedĹş wyzwalajÄ…ca<select name="trigger_answer_option_id" required>${Object.values(state.cfg.optionsById).filter(option=>option.code==='positive'||option.numericValue===0).map(option=>`<option value="${option.answerOptionId}">${esc(option.labelPl)}</option>`).join('')}</select></label><label class="field">Warunek strony<select name="source_side_condition"><option value="none">Bez strony</option><option value="any">Dowolna strona</option><option value="left">Lewa strona</option><option value="right">Prawa strona</option></select></label><label class="field">Test docelowy<select name="target_screen_test_id" required>${state.cfg.screenTests.filter(item=>item.isActive).map(item=>`<option value="${item.screenTestId}">${esc(state.cfg.testsById[item.testId]?.name||item.screenTestId)}</option>`).join('')}</select></label><label class="field">Wynik koĹ„cowy<input name="effect_value" type="number" min="0" max="3" value="0" required></label><label class="field">Przyczyna<textarea name="reason_template" required></textarea></label><button class="btn btn-primary">UtwĂłrz reguĹ‚Ä™</button></form></section>`;document.querySelector('#rule-form').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));try{await query(sb.from('effect_rules').insert({effect_rule_id:`effect_rule_${crypto.randomUUID()}`,screen_type_id:state.cfg.screenTypes[0].screen_type_id,source_test_field_id:values.source_test_field_id,trigger_answer_option_id:values.trigger_answer_option_id,source_side_condition:values.source_side_condition,target_screen_test_id:values.target_screen_test_id,effect_type:'set_final_score',effect_value:Number(values.effect_value),is_active:true,reason_template:values.reason_template}));closeModal();notify('ReguĹ‚a zostaĹ‚a utworzona.');showConfig()}catch(error){fail(error)}}}
document.addEventListener('click',event=>{if(event.target.closest('button[data-action="new-rule"]'))openRuleForm()});
document.addEventListener('click',event=>{const action=event.target.closest('button')?.dataset.action;if(!state.assessment||!['next-step','previous-step'].includes(action))return;history.pushState({route:'assessment',clientId:state.assessment.client.clientId,step:state.assessment.step},'',`#assessment/${state.assessment.client.clientId}/${state.assessment.step}`)});
const configButtonObserver=new MutationObserver(()=>{if(state.profileUser?.role!=='admin')return;const heading=[...document.querySelectorAll('h2')].find(item=>item.textContent.includes('ReguĹ‚y clearing'));if(heading&&!heading.parentElement.querySelector('[data-action="new-rule"]'))heading.parentElement.insertAdjacentHTML('beforeend','<button class="btn btn-primary" data-action="new-rule">Dodaj reguĹ‚Ä™</button>')});configButtonObserver.observe(app,{childList:true,subtree:true});
window.addEventListener('popstate',()=>{const route=history.state?.route;if(!state.user)return;if(route==='profile'&&history.state.clientId)return showProfile(history.state.clientId);if(route==='assessment'&&state.assessment){if(Number.isInteger(history.state.step))state.assessment.step=history.state.step;return renderAssessment()}if(route==='config')return showConfig();return showClients()});
boot().catch(renderFatal);
async function renderReportHistory(){const items=await query(sb.from('report_instances').select('*').eq('client_id',state.profile.client.clientId).eq('document_status','ready').order('generated_at',{ascending:false}));if(!items.length)return;app.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:20px"><header class="panel-head"><h3>Wygenerowane raporty</h3><small>Niezmienne snapshoty</small></header>${items.map(item=>`<div class="history-row"><span><strong>${new Date(item.generated_at).toLocaleDateString('pl-PL')}</strong><br><small>${esc(item.report_profile_code)} Â· generator ${esc(item.generator_version)}</small></span><button class="btn" data-report-path="${esc(item.pdf_storage_path)}">Pobierz PDF</button></div>`).join('')}</section>`)}

function openRecommendationForm(){const assessment=state.profile.latestAssessment;modal.hidden=false;modal.innerHTML=`<section class="modal"><header class="modal-head"><h2>Nowe zalecenie</h2><button class="icon-btn" data-action="close-modal">Ă—</button></header><form id="recommendation-form" class="form-stack"><label class="field">PowiÄ…zany test<select name="test_id"><option value="">OgĂłlne</option>${state.cfg.tests.filter(t=>t.isActive).map(t=>`<option value="${t.testId}">${esc(t.name)}</option>`).join('')}</select></label><label class="field">Priorytet<select name="priority"><option value="1">1 Â· wysoki</option><option value="2" selected>2 Â· Ĺ›redni</option><option value="3">3 Â· niski</option></select></label><label class="field">TreĹ›Ä‡<textarea name="content" required></textarea></label><label class="field">CzÄ™stotliwoĹ›Ä‡<input name="frequency" placeholder="np. 3 razy w tygodniu"></label><label class="field">Czas trwania<input name="duration" placeholder="np. 4 tygodnie"></label><button class="btn btn-primary">Zapisz zalecenie</button></form></section>`;document.querySelector('#recommendation-form').onsubmit=async event=>{event.preventDefault();try{const values=Object.fromEntries(new FormData(event.currentTarget));await query(sb.from('trainer_recommendations').insert({client_id:state.profile.client.clientId,assessment_id:assessment.assessmentId,author_id:state.user.id,test_id:values.test_id||null,priority:Number(values.priority),content:values.content,frequency:values.frequency,duration:values.duration}));closeModal();notify('Zalecenie zostaĹ‚o zapisane.')}catch(error){fail(error)}}}
function openClientServiceForm(){modal.hidden=false;modal.innerHTML=`<section class="modal"><header class="modal-head"><h2>UsĹ‚uga raportowa</h2><button class="icon-btn" data-action="close-modal">Ă—</button></header><form id="service-form" class="form-stack"><label class="field">Nazwa usĹ‚ugi<input name="service_name" value="FMS Quick Screen" required></label><label class="field">Profil raportu<select name="report_profile_code"><option value="free_current_result">BieĹĽÄ…cy wynik</option><option value="assessment_report">Raport badania</option><option value="full_coaching_report">PeĹ‚ny raport trenerski</option></select></label><button class="btn btn-primary">Przyznaj usĹ‚ugÄ™</button></form></section>`;document.querySelector('#service-form').onsubmit=async event=>{event.preventDefault();try{const values=Object.fromEntries(new FormData(event.currentTarget));await query(sb.from('client_services').update({is_active:false}).eq('client_id',state.profile.client.clientId));await query(sb.from('client_services').insert({...values,client_id:state.profile.client.clientId,granted_by:state.user.id}));closeModal();notify('Profil usĹ‚ugi zostaĹ‚ ustawiony.')}catch(error){fail(error)}}}
document.addEventListener('click',event=>{const button=event.target.closest('button');const action=button?.dataset.action;if(action==='new-recommendation')openRecommendationForm();if(action==='client-service')openClientServiceForm();if(button?.dataset.addReportSection){const code=button.dataset.addReportSection;if(!state.report.enabledSections.includes(code)){state.report.requestedSections.push(code);state.report.enabledSections.push(code);const html=code==='history'?`<section class="report-section"><h2 class="report-section-title">Historia</h2>${historyMarkup(state.report)}</section>`:code==='test_descriptions'?`<section class="report-section"><h2 class="report-section-title">Opisy testĂłw i kryteria</h2><div class="report-descriptions">${reportDescriptionMarkup(state.report.descriptionItems)}</div></section>`:`<section class="report-section"><h2 class="report-section-title">Zalecenia trenera</h2>${state.report.recommendations.map(r=>`<div class="finding" data-status="${r.priority===1?'pain':'attention'}"><strong>${esc(r.tests?.name||r.category)}</strong><p>${esc(r.content)}</p><small>${esc([r.frequency,r.duration].filter(Boolean).join(' Â· '))}</small></div>`).join('')}</section>`;document.querySelector('.report-disclaimer')?.closest('.report-section')?.insertAdjacentHTML('beforebegin',html)}button.remove()}});
document.addEventListener('click',event=>{const action=event.target.closest('button')?.dataset.action;if(action==='open-criteria'){const sheet=document.querySelector('#criteria-sheet');if(sheet)sheet.hidden=false}if(action==='close-criteria'){const sheet=document.querySelector('#criteria-sheet');if(sheet)sheet.hidden=true}if(action==='new-assessment-nav'){notify('Wybierz klienta, dla ktĂłrego chcesz rozpoczÄ…Ä‡ badanie.');showClients()}if(action==='reports'){if(state.profile?.latestAssessment)showReport();else notify('Najpierw wybierz klienta z kompletnym badaniem.',true)}});


